def merker_vorbelegen(apps, schema_editor):
    """Höchste je vergebene Nummer = größere von Zähler und höchster Nummer in den vorhandenen Belegen (auch frühere Nummern
    umgewandelter Belege). Es wird nichts gelöscht."""
    Nummernkreis = apps.get_model("verkauf", "Nummernkreis")
    Beleg = apps.get_model("verkauf", "Beleg")
    Umwandlung = apps.get_model("verkauf", "BelegUmwandlung")
    quellen = {"WS", "BE", "WE", "RM"}  # liegen in anderen Tabellen: dort gilt der Zähler

    def zaehler(nummern):
        werte = [n.rsplit("-", 1)[-1] for n in nummern if n]
        return max((int(w) for w in werte if w.isdigit()), default=0)

    for kreis in Nummernkreis.objects.all():
        hoechste = kreis.letzte_nummer
        if kreis.art not in quellen:
            hoechste = max(hoechste, zaehler(Beleg.objects.filter(mandant_id=kreis.mandant_id, art=kreis.art, nummer__startswith=kreis.art)
                                             .values_list("nummer", flat=True)),
                           zaehler(Umwandlung.objects.filter(beleg__mandant_id=kreis.mandant_id, von_art=kreis.art)
                                   .values_list("von_nummer", flat=True)))
        kreis.hoechste_vergeben = hoechste
        kreis.save(update_fields=["hoechste_vergeben"])


